<?php
namespace App\Domain\Products; use App\Models\{Product,ProductCategory};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class ProductManager {public function save(array $d,?Product $p,int $user):Product{return DB::transaction(function()use($d,$p,$user){$p??=new Product;$d['updated_by']=$user;if(!$p->exists){$d['created_by']=$user;$d['status']='draft';$d['display_order']=(int)Product::max('display_order')+1;}else unset($d['status']);$p->fill($d)->save();$this->normalize();return $p;});}public function publish(Product $p):void{$this->required($p);$p->update(['status'=>'published','published_at'=>now(),'scheduled_for'=>null,'archived_at'=>null]);}public function schedule(Product $p,string $utc):void{$this->required($p);$p->update(['status'=>'scheduled','scheduled_for'=>$utc,'published_at'=>null,'archived_at'=>null]);}public function unpublish(Product $p):void{$p->update(['status'=>'draft','published_at'=>null,'scheduled_for'=>null,'archived_at'=>null]);}public function archive(Product $p):void{if(app(ProductDependencyInspector::class)->inspect($p)['blocked'])throw ValidationException::withMessages(['product'=>'Resolve active navigation, homepage, and incoming product references before archiving.']);$p->update(['status'=>'archived','archived_at'=>now(),'published_at'=>null,'scheduled_for'=>null]);}public function restore(Product $p):void{$p->update(['status'=>'draft','archived_at'=>null,'published_at'=>null,'scheduled_for'=>null]);}public function duplicate(Product $p,int $user):Product{return DB::transaction(function()use($p,$user){$copy=$p->replicate(['status','published_at','scheduled_for','archived_at','created_by','updated_by']);$copy->title.=' (Copy)';$copy->slug=$this->uniqueSlug($p->slug.'-copy');$copy->status='draft';$copy->published_at=$copy->scheduled_for=$copy->archived_at=null;$copy->created_by=$copy->updated_by=$user;$copy->display_order=(int)Product::max('display_order')+1;$copy->save();foreach(['editions','benefits','specifications','galleryItems','useCases','integrations'] as $rel)$p->{$rel}()->each(fn($c)=>$copy->{$rel}()->create($c->only($c->getFillable())));$p->featureGroups()->with('features')->each(function($g)use($copy){$ng=$copy->featureGroups()->create($g->only($g->getFillable()));$g->features->each(fn($f)=>$ng->features()->create($f->only($f->getFillable())));});return $copy;});}public function move(Product $p,string $dir):void{DB::transaction(function()use($p,$dir){$peer=Product::where('display_order',$dir==='up'?'<':'>',$p->display_order)->orderBy('display_order',$dir==='up'?'desc':'asc')->first();if($peer){$x=$p->display_order;$p->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$x]);}$this->normalize();});}public function saveCategory(array $d,?ProductCategory $c=null):ProductCategory{return DB::transaction(function()use($d,$c){$c??=new ProductCategory;if(!$c->exists)$d['display_order']=(int)ProductCategory::max('display_order')+1;$c->fill($d)->save();$this->normalizeCategories();return $c;});}public function moveCategory(ProductCategory $c,string $dir):void{DB::transaction(function()use($c,$dir){$p=ProductCategory::where('display_order',$dir==='up'?'<':'>',$c->display_order)->orderBy('display_order',$dir==='up'?'desc':'asc')->first();if($p){$x=$c->display_order;$c->update(['display_order'=>$p->display_order]);$p->update(['display_order'=>$x]);}$this->normalizeCategories();});}private function normalize():void{Product::orderBy('display_order')->orderBy('id')->get()->each(fn($p,$i)=>$p->display_order===$i+1?null:$p->updateQuietly(['display_order'=>$i+1]));}private function normalizeCategories():void{ProductCategory::orderBy('display_order')->orderBy('id')->get()->each(fn($c,$i)=>$c->display_order===$i+1?null:$c->updateQuietly(['display_order'=>$i+1]));}private function required(Product $p):void{if(!trim($p->title)||!trim($p->short_description))throw ValidationException::withMessages(['product'=>'A title and short description are required before publication.']);}private function uniqueSlug(string $base):string{$base=Str::slug(Str::lower($base))?:'product';$slug=$base;for($i=2;Product::where('slug',$slug)->exists();$i++)$slug=Str::limit($base,150,'')."-$i";return $slug;}}